#!/usr/bin/env bash
# G1 measurement driver: crucible-term vs foot in a nested `crucible --winit` (method of crucible-dev-env/docs/terminal-spike-2026-11.md).
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/g1/g1.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'g1.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

usage() {
	cat <<'USAGE'
Usage: g1.sh [--help|-h] [--build|--version] <subject>...

Measure each subject (`crucible-term`, `foot`), back-to-back in the order given, each in its own fresh nested
`crucible --winit` launched through `crucible msg run-on` into a scratch workspace (scratch-cterm-<driver>-<pid>; override with CTERM_SCRATCH_WS, which must start with scratch-; the live CDE_SOCKET is required; parent WAYLAND_DISPLAY=/run/user/1001/wayland-1). Per subject:
  spawn -> first drawn frame (WAYLAND_DEBUG), median of 5; PSS/RSS of the terminal subtree after a 4 s settle,
  median of 3; idle CPU over 60 s (utime+stime of the subtree); `time cat` of the 50 MB file, the escape-heavy
  and the unicode corpus, median of 3 each. Prints MEM/LAT/IDLE/THR lines and writes them to target/g1/<subject>.out.
Scratch lives in /tmp/cde-g1-<subject> (removed at exit); artifacts under target/g1/. Only pids recorded by this
script are ever signalled; nothing is started on the live focused workspace.

Environment: CDE (the crucible-dev-env checkout; default: crucible-dev-env beside this repo; the harness exits before launching anything if it is absent).
Environment (defaults): G1_CRUCIBLE (crucible-dev-env/target/release/crucible), G1_CT (target/release/cterm),
G1_FOOT (~/.local/bin/foot), G1_FOOT_INI (~/.config/foot/foot.ini), G1_CORPUS (crucible-dev-env/target/spike-core/corpus),
G1_GAP (10), G1_PARENT_WL (/run/user/1001/wayland-1), G1_RUNS (5), G1_IDLE_S (60), G1_WAIT_S (120, per throughput run).
Bash reasons: arrays for argv, process substitution, trap cleanup.
USAGE
}

# shellcheck source-path=SCRIPTDIR source=../lib/build-id.sh
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/build-id.sh"
# shellcheck source-path=SCRIPTDIR source=../lib/run-on.sh
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/run-on.sh"
case " $* " in *" --help "* | *" -h "*) usage; exit 0 ;; esac
build_flags "${BASH_SOURCE[0]}" "$@"

[ "$#" -ge 1 ] || { usage >&2; exit 2; }
for s in "$@"; do
	case $s in crucible-term | foot) ;; *) echo "g1.sh: unknown subject: $s" >&2; exit 2 ;; esac
done

HERE=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd -P)
R=$(cd "$HERE/../.." && pwd -P)
CDE=${CDE:-$R/../crucible-dev-env}
[ -d "$CDE" ] || { echo "HARNESS FAILURE: CDE checkout not found: $CDE (set CDE to a crucible-dev-env checkout)" >&2; exit 1; }
BIN=${G1_CRUCIBLE:-$CDE/target/release/crucible}
CT=${G1_CT:-$R/target/release/cterm}
FOOT=${G1_FOOT:-$HOME/.local/bin/foot}
FOOT_INI=${G1_FOOT_INI:-$HOME/.config/foot/foot.ini}
CORPUS=${G1_CORPUS:-$CDE/target/spike-core/corpus}
GAP=${G1_GAP:-10}
PARENT_WL=${G1_PARENT_WL:-/run/user/1001/wayland-1}
RUNS=${G1_RUNS:-5}
IDLE_S=${G1_IDLE_S:-60}
WAIT_S=${G1_WAIT_S:-120}
OUT=$R/target/g1
BIG=$OUT/50mb.txt
mkdir -p "$OUT"
# 50 MB file exactly as the spike: seq 1 8000000 | head -c 52428800
if [ ! -s "$BIG" ]; then
	seq 1 8000000 | head -c 52428800 >"$BIG" || true
fi
sha=$(sha256sum "$BIG" | cut -d' ' -f1)
[ "$sha" = 92535e5f4c51e88d630c220c2d5b60f102b5df7c1a570b2e75eb9c2f8161dc65 ] || { echo "g1.sh: 50 MB file sha mismatch: $sha" >&2; exit 1; }
for f in b.bin c.bin; do [ -s "$CORPUS/$f" ] || { echo "g1.sh: missing corpus $CORPUS/$f" >&2; exit 1; }; done

now() { perl -MTime::HiRes=time -e 'printf "%.6f\n", time'; } # libwayland stamps are CLOCK_REALTIME us mod 2^32
median() { sort -n | awk '{a[NR]=$1} END{ if(NR==0){print "NA"} else if(NR%2){print a[(NR+1)/2]} else {printf "%.3f\n",(a[NR/2]+a[NR/2+1])/2} }'; }

# "rss_kB pss_kB nprocs ticks" of the subtree rooted at pid $1 (ticks = utime+stime)
subtree() {
	perl -e '
  my $root=shift; my %kids;
  opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; push @{$kids{$1}},$p }
  my @q=($root); my ($rss,$pss,$n,$tk)=(0,0,0,0);
  while(my $p=shift @q){ push @q,@{$kids{$p}||[]};
    if(open(F,"<","/proc/$p/status")){ while(<F>){ $rss+=$1 if /^VmRSS:\s+(\d+)/ } close F; $n++ }
    if(open(F,"<","/proc/$p/smaps_rollup")){ while(<F>){ $pss+=$1 if /^Pss:\s+(\d+)/ } close F }
    if(open(F,"<","/proc/$p/stat")){ my $s=<F>; close F; $s=~/\) (.*)$/ and do { my @f=split / /,$1; $tk+=$f[11]+$f[12] } } }
  print "$rss $pss $n $tk\n"' "$1"
}

# first wl_surface.commit after ack_configure and a non-nil attach, ms after t0 (empty if none)
first_frame_ms() {
	perl -e '
  my $t0=shift; my $best; my $M=4294967296; my $t0u=int($t0*1e6)%$M;
  for my $f (@ARGV){ open(F,"<",$f) or next; my ($ack,$att)=(0,0);
    while(<F>){ next unless /^\[\s*([\d.]+)\](?:\[\w+\])?\s+(?:\{[^}]*\}\s+)?->\s+(\S+)\.(\w+)\((.*)\)/; my($ts,$obj,$req,$a)=($1,$2,$3,$4); my $d=($ts*1000-$t0u); $d+=$M while $d<0; $d-=$M while $d>=$M; next if $d>60e6;
      if($req eq "ack_configure"){$ack=1}
      elsif($ack && $req eq "attach" && $a!~/^nil/ ){$att=1}
      elsif($att && $req eq "commit"){ $best=$d if !defined($best)||$d<$best; last } } close F }
  printf "%.1f\n",$best/1000 if defined $best' "$@"
}

CPID=""
T=""
cleanup() {
	if [ -n "$T" ] && [ -f "$T/pids" ]; then
		while read -r p; do kill "$p" 2>/dev/null || true; done <"$T/pids"
	fi
	[ -z "$CPID" ] || run_on_close "$CPID"
	[ -n "$CPID" ] && kill "$CPID" 2>/dev/null || true
	[ -n "$T" ] && rm -rf "$T"
	return 0
}
trap cleanup EXIT

measure() {
	local NAME=$1 PROG PRE
	T=/tmp/cde-g1-$NAME
	rm -rf "$T"
	mkdir -p "$T/config/cde" "$T/config/crucible-term" "$T/state" "$T/data" "$T/run"
	chmod 700 "$T/run"
	: >"$T/pids"
	case $NAME in
	crucible-term) PROG=$CT PRE="" ;;
	foot)
		cp "$FOOT_INI" "$T/foot.ini"
		PROG=$FOOT PRE="--config=$T/foot.ini"
		;;
	esac
	printf 'PROG=%s\nPRE=%q\n' "$PROG" "$PRE" >"$T/term.env"
	# crucible-term config equivalent to the user's foot.ini (read through the nested XDG_CONFIG_HOME)
	cat >"$T/config/crucible-term/config.kdl" <<'KDL'
font "Bitstream Vera Sans Mono" size=14
colors {
    foreground "#c5c8c6"
    background "#000000"
    cursor "#c5c8c6"
    alpha 0.8
    palette 0 "#282a2e"
    palette 1 "#a54242"
    palette 2 "#649440"
    palette 3 "#de935f"
    palette 4 "#5f819d"
    palette 5 "#85678f"
    palette 6 "#5e8d87"
    palette 7 "#707880"
    palette 8 "#373b41"
    palette 9 "#cc6666"
    palette 10 "#8abd68"
    palette 11 "#f0c674"
    palette 12 "#81a2be"
    palette 13 "#b294bb"
    palette 14 "#8abeb7"
    palette 15 "#c5c8c6"
}
scrollback lines=10000
pad 2 2
center
cursor shape="block" blink=#true
KDL
	cat >"$T/config/cde/config.kdl" <<KDL
tiling {
    terminal gap=(px)$GAP ring=(px)2 ring-inset=(px)4 frame="#3a3a3a"
    terminal-args "-o" "pad={gap}x{gap} center"
}
terminal "$HERE/term.sh" exec-flag="-e"
KDL
	# in-terminal helper scripts: time cat of one file, ns appended to $T/thr-<tag>.txt
	local tag file
	for tag in big:"$BIG" esc:"$CORPUS/b.bin" uni:"$CORPUS/c.bin"; do
		file=${tag#*:}
		tag=${tag%%:*}
		printf '#!/bin/sh\ns=$(date +%%s%%N); cat "%s"; e=$(date +%%s%%N); echo $((e-s)) >> "%s/thr-%s.txt"\n' "$file" "$T" "$tag" >"$T/thr-$tag.sh"
		chmod +x "$T/thr-$tag.sh"
	done
	msg() { CDE_SOCKET=$T/run/cde/wayland-1.sock "$BIN" msg "$@"; }

	run_on_launch g1 "$T" "$T/log" G1_DIR="$T" XDG_CONFIG_HOME="$T/config" XDG_STATE_HOME="$T/state" XDG_DATA_HOME="$T/data" XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY="$PARENT_WL" -- "$BIN" --winit || return 1
	CPID=$RUN_ON_PID
	local i
	for i in $(seq 1 50); do
		[ -S "$T/run/cde/wayland-1.sock" ] && ls "$T"/run/wayland-* >/dev/null 2>&1 && break
		sleep 0.2
	done
	kill -0 "$CPID" 2>/dev/null || { echo "compositor died: see $T/log"; tail -3 "$T/log"; return 1; }
	echo "== $NAME compositor pid $CPID"
	echo "VERSION: $("$PROG" --version 2>&1 | head -1)"
	echo "NESTED_CONFIG: gap=$GAP terminal-args -o pad={gap}x{gap} center"
	sleep 3

	# memory + idle CPU: 3 fresh windows, 4 s settle; idle CPU sampled on window 1
	local k P rss pss n tk0 tk1 t0 t1 PSS_LIST="" RSS_LIST="" hz
	hz=$(getconf CLK_TCK)
	for k in 1 2 3; do
		msg exec run-terminal >/dev/null
		sleep 4
		P=$(tail -1 "$T/pids")
		read -r rss pss n tk0 < <(subtree "$P")
		echo "MEM run $k: pss_kB=$pss rss_kB=$rss procs=$n pid=$P"
		PSS_LIST="$PSS_LIST$pss"$'\n'
		RSS_LIST="$RSS_LIST$rss"$'\n'
		if [ "$k" = 1 ]; then
			t0=$(now)
			sleep "$IDLE_S"
			t1=$(now)
			read -r rss pss n tk1 < <(subtree "$P")
			echo "IDLE_CPU: ticks=$((tk1 - tk0)) over $(perl -e 'printf "%.2f", $ARGV[1]-$ARGV[0]' "$t0" "$t1") s -> $(perl -e 'printf "%.3f", 100*($ARGV[0]/$ARGV[3])/($ARGV[2]-$ARGV[1])' "$((tk1 - tk0))" "$t0" "$t1" "$hz") % of one core (procs=$n)"
		fi
		kill "$P" 2>/dev/null || true
		sleep 1.5
	done
	echo "PSS_MEDIAN_KB $(printf '%s' "$PSS_LIST" | median)"
	echo "RSS_MEDIAN_KB $(printf '%s' "$RSS_LIST" | median)"

	# latency
	touch "$T/debug"
	local base lat LATS="" t0l p
	for i in $(seq 1 "$RUNS"); do
		base=$(wc -l <"$T/pids")
		t0l=$(now)
		msg exec run-terminal >/dev/null
		lat=""
		for _ in $(seq 1 100); do
			sleep 0.1
			lat=$(first_frame_ms "$t0l" "$T"/wl.*.log 2>/dev/null || true)
			[ -n "$lat" ] && break
		done
		echo "latency run $i: ${lat:-FAIL} ms"
		[ -n "$lat" ] && LATS="$LATS$lat"$'\n'
		for p in $(tail -n +"$((base + 1))" "$T/pids"); do kill "$p" 2>/dev/null || true; done
		rm -f "$T"/wl.*.log
		sleep 1.5
	done
	echo "LATENCY_MEDIAN_MS $(printf '%s' "$LATS" | median)"
	rm -f "$T/debug"

	# throughput
	local tg ns
	for tg in big esc uni; do
		rm -f "$T/thr-$tg.txt"
		for i in 1 2 3; do
			msg exec run-in-terminal "$T/thr-$tg.sh" >/dev/null || msg run-in-terminal "$T/thr-$tg.sh" >/dev/null || true
			for _ in $(seq 1 $((WAIT_S * 2))); do
				[ "$(cat "$T/thr-$tg.txt" 2>/dev/null | wc -l)" -ge "$i" ] && break
				sleep 0.5
			done
			sleep 1.5
		done
		ns=$(cat "$T/thr-$tg.txt" 2>/dev/null | tr '\n' ' ' || true)
		echo "THROUGHPUT $tg runs (ns): $ns"
		echo "THROUGHPUT_${tg}_MEDIAN_S $(awk '{printf "%.3f\n",$1/1e9}' "$T/thr-$tg.txt" 2>/dev/null | median)"
		for p in $(cat "$T/pids"); do kill "$p" 2>/dev/null || true; done
		sleep 1
	done

	msg exec quit >/dev/null || true
	sleep 2
	if kill -0 "$CPID" 2>/dev/null; then run_on_close "$CPID"; kill "$CPID" 2>/dev/null || true; fi
	echo "== $NAME done"
}

for s in "$@"; do
	measure "$s" >"$OUT/$s.out" 2>&1 || echo "g1.sh: $s measurement failed (see $OUT/$s.out)" >&2
	cat "$OUT/$s.out"
	cleanup
	CPID=""
	T=""
done
